function boot(){const c=C();if(!c||!c.__gdPatched||!A()?.SceneRenderer)return setTimeout(boot,100);rendererPatch();controllerPatch();installUI();bindUI();syncAttachedConnectors(c);c.render?.();toast('Google Drawings complete editing layer active: all art objects are selectable and movable.','success')}
